import json

with open('output/pages.json') as f:
    data = json.load(f)

for page in data['pages']:
    print(f'Page {page[\"page_no\"]}: column_count={page[\"column_count\"]}, elements={len(page[\"elements\"])}')
    cols = {}
    for e in page['elements']:
        cols.setdefault(e['column'], []).append(e)
    for c in sorted(cols):
        print(f'  Column {c}: {len(cols[c])} elements')
        for e in cols[c]:
            b = e['bbox']
            print(f'    {e[\"id\"]} bbox=[{b[0]:.1f}, {b[1]:.1f}, {b[2]:.1f}, {b[3]:.1f}]')
    print()
